import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import * as esbuild from "esbuild";

const packageRoot = fileURLToPath(new URL("..", import.meta.url));
const outputPath = path.join(packageRoot, "src/templates/runtime-bundle.generated.ts");

const result = await esbuild.build({
  absWorkingDir: packageRoot,
  alias: {
    // Avoid environment-specific package build artifacts when generating the checked-in bundle.
    "@voidhash/paywalls": path.join(packageRoot, "../../libraries/paywalls/src/runtime/config.ts"),
  },
  entryPoints: ["src/runtime/hydrate.tsx"],
  bundle: true,
  define: {
    "process.env.NODE_ENV": '"production"',
  },
  format: "iife",
  jsx: "automatic",
  jsxImportSource: "preact",
  metafile: false,
  minify: true,
  sourcemap: false,
  target: "es2020",
  treeShaking: true,
  write: false,
});

const bundle = result.outputFiles[0]?.text;
if (bundle === undefined) {
  throw new Error("esbuild did not emit the paywall hydration runtime");
}

const source = `/** Generated by scripts/generate-runtime-bundle.mjs. */\nexport const PAYWALL_RUNTIME_BUNDLE = ${JSON.stringify(bundle)};\n`;

if (process.argv.includes("--check")) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== source) {
    throw new Error("The generated paywall runtime is stale; run pnpm runtime:generate");
  }
} else {
  await writeFile(outputPath, source);
}
